using System.Security.Cryptography;using System.Text;using System.Windows;
namespace CentroComputo.Client;
public partial class AdminRecoveryWindow:Window{public AdminRecoveryWindow()=>InitializeComponent();private void Recover_Click(object sender,RoutedEventArgs e){var stored=Environment.GetEnvironmentVariable("CENTRO_RECOVERY_HASH");if(string.IsNullOrEmpty(stored)){Error.Text="Credencial no aprovisionada. Contacta a TI.";return;}try{var parts=stored.Split(':',2);var salt=Convert.FromBase64String(parts[0]);var expected=Convert.FromBase64String(parts[1]);var actual=Rfc2898DeriveBytes.Pbkdf2(Password.Password,salt,200_000,HashAlgorithmName.SHA256,expected.Length);if(CryptographicOperations.FixedTimeEquals(actual,expected)){DialogResult=true;return;}}catch{}Error.Text="Credencial inválida";}}
